WITH kept AS (SELECT s.* FROM orders s WHERE EXISTS (SELECT 1 FROM payments c WHERE c.order_id = s.id AND c.paid_at < s.order_date)) SELECT s.id, s.store_id, s.channel, s.amount, s.discount, s.shipping_fee, CASE WHEN channel RLIKE '^(mobile|web)$' THEN 'EXTENDED' WHEN channel RLIKE '^(store|partner)$' THEN 'OTHER_ZONE' ELSE 'GROUP_A' END AS channel_zone, (SELECT MIN(o2.shipping_fee) FROM orders o2 WHERE o2.store_id = s.store_id) AS min_order_shipping_fee FROM kept s ORDER BY channel DESC;
